// Patch SocketModeClient.connect to accept per-instance timeout overrides.
// This allows us to inject clientPingTimeout/serverPingTimeout from account config
// without needing to fork @slack/bolt.
const OriginalSocketModeClientConnect = SocketModeClient.prototype.connect as (
  this: SocketModeClient & {
    clientPingTimeoutMS?: number;
    serverPingTimeoutMS?: number;
  },
) => Promise<unknown>;
(SocketModeClient.prototype.connect as Function) = async function () {
  // Apply any per-instance overrides set by the account config (injected via App.start patch below)
  const clientPingTimeout =
    (this as typeof this & { _openClawClientPingTimeout?: number })._openClawClientPingTimeout ??
    this.clientPingTimeoutMS;
  const serverPingTimeout =
    (this as typeof this & { _openClawServerPingTimeout?: number })._openClawServerPingTimeout ??
    this.serverPingTimeoutMS;
  (this as typeof this & { clientPingTimeoutMS: number }).clientPingTimeoutMS = clientPingTimeout;
  (this as typeof this & { serverPingTimeoutMS: number }).serverPingTimeoutMS = serverPingTimeout;
  return OriginalSocketModeClientConnect.call(this);
};

// Patch App.start to inject Socket Mode ping timeout config from account settings
// into the receiver's SocketModeClient before starting.
const OriginalAppStart = App.prototype.start;
(App.prototype as typeof App.prototype & { start: Function }).start = async function (...args: unknown[]) {
  const receiver = (this as unknown as { receiver: { client?: SocketModeClient } }).receiver;
  if (receiver?.client) {
    const clientPingTimeout = (this as typeof this & { _openClawClientPingTimeout?: number })._openClawClientPingTimeout;
    const serverPingTimeout = (this as typeof this & { _openClawServerPingTimeout?: number })._openClawServerPingTimeout;
    if (clientPingTimeout !== undefined) {
      (receiver.client as typeof receiver.client & { _openClawClientPingTimeout?: number })._openClawClientPingTimeout = clientPingTimeout;
    }
    if (serverPingTimeout !== undefined) {
      (receiver.client as typeof receiver.client & { _openClawServerPingTimeout?: number })._openClawServerPingTimeout = serverPingTimeout;
    }
  }
  return OriginalAppStart.apply(this, args) as unknown;
};

